const pSPTxnsOfPayout = `-- name: PSPTxnsOfPayout :many
SELECT id, connector_id, txn_id, type, category, source_kind, source_id, currency, gross, fee, net, available_on, payout_id, provider_at, seen_at
  FROM fyniq.psp_txn WHERE connector_id = $1 AND payout_id = $2 ORDER BY provider_at, txn_id
`

type PSPTxnsOfPayoutParams struct {
	ConnectorID uuid.UUID
	PayoutID    *string
}

type PSPTxnsOfPayoutRow struct {
	ID          uuid.UUID
	ConnectorID uuid.UUID
	TxnID       string
	Type        string
	Category    string
	SourceKind  *string
	SourceID    *string
	Currency    string
	Gross       string
	Fee         string
	Net         string
	AvailableOn pgtype.Date
	PayoutID    *string
	ProviderAt  time.Time
	SeenAt      time.Time
}

func (q *Queries) PSPTxnsOfPayout(ctx context.Context, arg PSPTxnsOfPayoutParams) ([]PSPTxnsOfPayoutRow, error) {
	rows, err := q.db.Query(ctx, pSPTxnsOfPayout, arg.ConnectorID, arg.PayoutID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PSPTxnsOfPayoutRow
	for rows.Next() {
		var i PSPTxnsOfPayoutRow
		if err := rows.Scan(
			&i.ID,
			&i.ConnectorID,
			&i.TxnID,
			&i.Type,
			&i.Category,
			&i.SourceKind,
			&i.SourceID,
			&i.Currency,
			&i.Gross,
			&i.Fee,
			&i.Net,
			&i.AvailableOn,
			&i.PayoutID,
			&i.ProviderAt,
			&i.SeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

