const sweptPSPAccount = `-- name: SweptPSPAccount :execrows
UPDATE fyniq.psp_account SET swept_through = COALESCE($1::date, swept_through),
  swept_at = CASE WHEN $1::date IS NULL THEN swept_at ELSE $2::timestamptz END,
  sweep_error = $3
WHERE money_account_id = $4
`

type SweptPSPAccountParams struct {
	SweptThrough   pgtype.Date
	SweptAt        time.Time
	SweepError     *string
	MoneyAccountID uuid.UUID
}

func (q *Queries) SweptPSPAccount(ctx context.Context, arg SweptPSPAccountParams) (int64, error) {
	result, err := q.db.Exec(ctx, sweptPSPAccount,
		arg.SweptThrough,
		arg.SweptAt,
		arg.SweepError,
		arg.MoneyAccountID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

